import random
random.seed(7)
def sq(x):return "'"+x.replace("'","''")+"'"
out=["-- 문제 은행. 다시 실행해도 같은 문제는 중복으로 들어가지 않고 내용만 갱신된다(문제 글 기준).",
     'delete from hq_bank where q in (\'1997년 IMF 구제금융을 신청할 당시 대통령은?\',\'MBTI에서 "E"가 뜻하는 것은?\',\'엑셀에서 합계를 구하는 함수는?\',\'초성 퀴즈! "ㄱㄴㅅㅌㅇ", 2012년 전 세계가 말춤을 춘 노래는?\',\'듀스의 멤버는 김성재와 누구?\',\'"잘못된 만남"을 부른 가수는?\',\'함흥냉면은 원래 비빔냉면으로 유명하다.\',\'2018 평창 동계올림픽의 마스코트는?\',\'"포기하면 그 순간이 바로 시합 종료예요." 슬램덩크에서 이 말을 한 사람은?\',\'골프에서 파(Par)보다 2타 적게 치면?\',\'100명에게 물었습니다! 회식 2차로 가장 가고 싶은 곳은?\');',
     "delete from hq_bank where cat = '노래' and media not like 'https://%';",
     "-- 보기 순서는 여기서 한 번 섞어서 넣는다(정답이 늘 1번이 되지 않게)."]
for row in B:
  c,d,t,q,o,a,n,h,tp=row[:9]; media=row[9]; pack=row[10]
  if media: q=f'{q} ({media.split()[0]} 편)' if False else q
  if t=='mc':
    ans=o[a]; o=o[:]; random.shuffle(o); a=o.index(ans)
  if a is None: a='null'
  out.append(f"insert into hq_bank (cat,diff,type,q,opts,answer,note,host,topic,media,pack) values ({sq(c)},{d},{sq(t)},{sq(q)},{sq(json.dumps(o,ensure_ascii=False))}::jsonb,{a},{sq(n)},{sq(h)},{sq(tp)},{sq(media)},{sq(pack)}) on conflict (q, media) do update set pack=excluded.pack, cat=excluded.cat, diff=excluded.diff, type=excluded.type, opts=excluded.opts, answer=excluded.answer, note=excluded.note, host=excluded.host, topic=excluded.topic;")
open('04_bank.sql','w').write("\n".join(out)+"\n")
